use vstd::prelude::*;

verus! {

    /// copy takes a reference to a Vec<i8> and produces a brand new Vec<i8>
    /// that has the same length and the same contents element‐wise.
    fn copy(arr: &Vec<i8>) -> (res: Vec<i8>)
        ensures
            // The result has exactly the same length as the input
            res.len() == arr.len(),
            // And for every valid index i, the elements agree
            forall |i: usize| i < arr.len() ==> res.index(i) == arr.index(i),
    {
        // Start with an empty result vector, pre‐allocating the needed capacity.
        let mut res: Vec<i8> = Vec::with_capacity(arr.len());
        let mut idx: usize = 0;

        // Loop until we've copied all elements.
        while idx < arr.len()
            invariant
                // never walk past the end
                idx <= arr.len(),
                // we have pushed exactly idx elements so far
                res.len() == idx,
                // and for all j < idx, the elements agree
                forall |j: usize| j < idx ==> res.index(j) == arr.index(j),
            decreases
                // this measure goes down on each iteration, so we terminate
                arr.len() - idx,
        {
            let x: i8 = arr.index(idx);
            res.push(x);
            idx += 1;
        }

        // Now idx == arr.len(), so by the invariant
        // res.len() == arr.len() and for all i < arr.len() the elements agree.
        res
    }
}

